fn route_check(j:&Value,log:&str){let rows=log.lines().filter_map(|l|l.strip_prefix("FINALIZE_DRAIN_BUNDLE ")).collect::<Vec<_>>();if j["variant"]=="accepted"{assert!(rows.is_empty());return;}assert_eq!(rows.len(),1);let x:Value=serde_json::from_str(rows[0]).unwrap();assert_eq!(x["enabled"],j["variant"]=="ON");}
fn prepare(){
assert!(!r("plan.json").exists());assert_eq!(read(r("native/result.json"))["status"],"complete");assert_eq!(read(r("links/result.json"))["status"],"complete");for mode in["OFF","ON"]{for(s,n)in[("core",128),("raw",2),("cubic",6)]{let t=read(r(format!("native/{s}-{mode}/tests.json")));assert_eq!(t["passed_tests"].as_array().unwrap().len(),n);assert_eq!(t["unfiltered"],s!="raw");}}
let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r("link-pins.json"))).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}assert_eq!(hash(ACCEPTED),"6d83f1d6fda6f16576cb351b81789e8d26a6177cc0f26f169a3dc98448c0e661");pin(&mut pins,ACCEPTED);let linked=read(r("links/sdk/artifacts.json"));let fresh=linked["binary"].as_str().unwrap();assert_eq!(hash(fresh),linked["binary_sha256"]);for(p,h)in linked["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin(&mut pins,p);}pin(&mut pins,fresh);let cmd=read(r("links/sdk/command.json"));for flag in["-O","target-cpu=native","lto=fat","codegen-units=1"]{assert!(cmd["argv"].as_array().unwrap().iter().any(|x|x==flag));}
let ids=json!({"accepted":{"binary":ACCEPTED,"sha256":hash(ACCEPTED)},"OFF":{"binary":fresh,"sha256":hash(fresh)},"ON":{"binary":fresh,"sha256":hash(fresh)}});save(r("identities.json"),&ids);let prior_path="/home/ubuntu/src/zopro-perf-work/chunk-grouping176/missing-six/proof-sha256-after.json";let prior=read(prior_path);assert_eq!(prior.as_array().unwrap().len(),29461);pin(&mut pins,prior_path);save(r("prior-proof-sha256.json"),&prior);
let cases=read("/home/ubuntu/src/zopro-perf-work/postgroup-phi176/cases.json").as_array().unwrap().clone();assert_eq!(cases.len(),10);save(r("cases.json"),&json!(cases));let mut base=read("/home/ubuntu/src/zopro-perf-work/sdk-link-flags176/environment.json");for k in["RUSTFLAGS","CARGO_TARGET_DIR","CARGO_BUILD_JOBS"]{base.as_object_mut().unwrap().remove(k);}for dir in["proofs","stat","perf"]{fs::create_dir_all(r(dir)).unwrap();}for f in["ctl","ack"]{assert!(Command::new("mkfifo").arg(r(f)).status().unwrap().success());}
let(mut jobs,mut steps)=(vec![],vec![]);for c in &cases{for v in VS{add_job(c,v,0,"preflight",&base,&ids,&mut jobs,&mut steps);steps.push(verify_step(jobs.last().unwrap()));}}steps.push(step("preflight-routes",vec![r("capture-helper").display().to_string(),"preflight-routes".into()]));
for b in 0..15{let mut order=(0usize..10).collect::<Vec<_>>();order.rotate_left(b%10);if b%2==1{order.reverse();}let mut variants=VS;variants.rotate_left(b%3);if b%2==1{variants.reverse();}for i in order{for v in variants{add_job(&cases[i],v,b,"latency",&base,&ids,&mut jobs,&mut steps);}}}
for panel in["stat","cycles"]{for workers in[16,32]{let c=cases.iter().find(|c|c["shape"]=="1x2"&&c["workers"]==workers).unwrap();for v in VS{add_job(c,v,0,panel,&base,&ids,&mut jobs,&mut steps);}}}
assert_eq!(jobs.len(),492);for j in jobs.iter().filter(|j|j["panel"]!="preflight"){steps.push(verify_step(j));}
for j in jobs.iter().filter(|j|j["panel"]=="cycles"){let n=j["name"].as_str().unwrap();let file=j["data"].as_str().unwrap();steps.push(step(format!("own-{n}"),vec!["sudo".into(),"-n".into(),"chown".into(),"ubuntu:ubuntu".into(),file.into()]));for(kind,argv)in[("decode",vec!["perf","script","--header","--ns","-i",file,"-F","pid,tid,cpu,time,period,ip,sym"].into_iter().map(String::from).collect()),("events",vec!["perf","evlist","-v","-i",file].into_iter().map(String::from).collect()),("loss",vec![r("capture-helper").display().to_string(),"loss".into(),file.into()]),("metadata",vec!["perf","script","--header","--show-mmap-events","--show-task-events","--ns","-i",file,"-F","pid,tid,cpu,time,period,ip,sym"].into_iter().map(String::from).collect())]{steps.push(step(format!("{kind}-{n}"),argv));}}
assert_eq!(steps.len(),1015);assert_eq!(jobs.iter().map(|j|j["rounds"].as_u64().unwrap()+3).sum::<u64>(),34698);save(r("jobs.json"),&json!(jobs));for c in &cases{for key in["image","request","raw","key"]{pin(&mut pins,c[key].as_str().unwrap());}assert_eq!(hash(c["image"].as_str().unwrap()),c["image_sha256"]);}for e in fs::read_dir("/home/ubuntu/src/zopro-perf-work/sdk-control-copies/lagrange-cache").unwrap(){pin(&mut pins,e.unwrap().path());}
for p in[VERIFY,X,"/usr/bin/perf","/home/ubuntu/src/zopro-perf-work/sdk-link-flags176/environment.json"]{pin(&mut pins,p);}for f in["capture.rs","capture-prepare.rs","analysis.rs","sampling.rs","counter.rs","metadata.rs","capture-helper","design.md","source-audit.json","identities.json","cases.json","jobs.json","prior-proof-sha256.json"]{pin(&mut pins,r(f));}save(r("pins.json"),&json!(pins));save(r("plan.json"),&json!({"version":1,"source_pins":r("pins.json"),"steps":steps}));println!("Frozen1015commands/492exports/34698SDKrequests;all8gain/all10nonreg+calibration;6stats6profilesafterALL450latencies;no timingyet");
}
fn preflight_routes(){let jobs=read(r("jobs.json"));let mut n=0;for j in jobs.as_array().unwrap().iter().filter(|j|j["panel"]=="preflight"){let name=j["name"].as_str().unwrap();let log=fs::read_to_string(r(format!("runs/{name}/stdout.log"))).unwrap();route_check(j,&log);assert!(fs::read_to_string(r(format!("runs/verify-{name}/stdout.log"))).unwrap().lines().any(|l|l.starts_with("VERIFIED ")));n+=1;}assert_eq!(n,30);println!("30preflightproofbindings+bundleconfigurationchecksPASSbeforelatency");}
